"""CSV 读写工具。

读取时自动适配 UTF-8（含 BOM）与 GBK/GB18030 编码：
先按 UTF-8 解码（同时剥离 UTF-8 BOM），失败后回退 GB18030。
写出统一使用 UTF-8。
"""
from __future__ import annotations

import csv
import io
from pathlib import Path


def _decode_csv(data: bytes) -> str:
    """把 CSV 字节解码为文本，兼容 UTF-8 BOM 与 GBK 系编码。"""
    try:
        # utf-8-sig 会在解码时剥离开头的 UTF-8 BOM。
        return data.decode("utf-8-sig")
    except UnicodeDecodeError as utf8_error:
        # 若文件带 BOM 但正文不是 UTF-8，先去掉 BOM 再按 GB18030 解码。
        if data.startswith(b"\xef\xbb\xbf"):
            data = data[len(b"\xef\xbb\xbf") :]
        try:
            return data.decode("gb18030")
        except UnicodeDecodeError:
            # 两种编码都无法解码时保留原有异常类型，避免调用方契约变化。
            raise utf8_error


def read_rows(path: str | Path) -> list[list[str]]:
    """读取整个 CSV，返回行列表。

    自动识别 UTF-8（含 BOM）与 GBK/GB18030；BOM 不会残留到首列表头。
    """
    data = Path(path).read_bytes()
    text = _decode_csv(data)
    return [row for row in csv.reader(io.StringIO(text, newline=""))]

